/* Binary assets linked into the ELF; generated by tools/build_*.py. */
    .section .rodata
    .balign 32
    .global _rl_textures_pak
_rl_textures_pak:
    .incbin "assets/generated/textures.pak"

    .balign 32
    .global _rl_sfx_pak
_rl_sfx_pak:
    .incbin "assets/generated/sfx.pak"

    .balign 32
    .global _rl_level_bin
_rl_level_bin:
    .incbin "assets/generated/level.bin"
